(function(){try{var d=JSON.parse(localStorage.getItem('ba3_founder')||'null');if(!d)return;var e=document.getElementById('fphoto');if(d.img&&e)e.innerHTML='<img src="'+d.img+'" alt="Advocate Manju S Prakash">';if(d.note){var n=document.getElementById('fnote');if(n){n.innerHTML='';d.note.split(/\n\s*\n/).forEach(function(t){var p=document.createElement('p');p.textContent=t;n.appendChild(p)})}}}catch(e){}})();
